const shiftDeployTargetHostPositions = `-- name: ShiftDeployTargetHostPositions :exec
UPDATE "DeployTargetHosts"
SET "Position" = "Position" + 100
WHERE "TargetId" = $1 AND "OrganizationId" = $2 AND NOT "IsDeleted"
`

type ShiftDeployTargetHostPositionsParams struct {
	TargetID       uuid.UUID
	OrganizationID uuid.UUID
}

func (q *Queries) ShiftDeployTargetHostPositions(ctx context.Context, arg ShiftDeployTargetHostPositionsParams) error {
	_, err := q.db.Exec(ctx, shiftDeployTargetHostPositions, arg.TargetID, arg.OrganizationID)
	return err
}

const syncDeployTargetHostPaths = `-- name: SyncDeployTargetHostPaths :exec
UPDATE "DeployTargetHosts"
SET "DeployPath" = $1, "UpdatedAt" = $2
WHERE "TargetId" = $3 AND "OrganizationId" = $4 AND NOT "IsDeleted" AND "DeployPath" <> $1
`

type SyncDeployTargetHostPathsParams struct {
	DeployPath     string
	Now            time.Time
	TargetID       uuid.UUID
	OrganizationID uuid.UUID
}

func (q *Queries) SyncDeployTargetHostPaths(ctx context.Context, arg SyncDeployTargetHostPathsParams) error {
	_, err := q.db.Exec(ctx, syncDeployTargetHostPaths,
		arg.DeployPath,
		arg.Now,
		arg.TargetID,
		arg.OrganizationID,
	)
	return err
}

