const updateDeployTarget = `-- name: UpdateDeployTarget :one
UPDATE "DeployTargets"
SET "Username" = $1,
    "PublicKey" = CASE WHEN "KeySecretName" IS DISTINCT FROM $2::text THEN NULL ELSE "PublicKey" END,
    "KeySecretName" = $2::text, "DeployPath" = $3,
    "KeepReleases" = $4, "Settings" = $5, "AllowedImages" = $6::text[],
    "Version" = "Version" + 1, "UpdatedAt" = $7
WHERE "Id" = $8 AND "OrganizationId" = $9 AND NOT "IsDeleted"
RETURNING "Id", "CreatedAt", "UpdatedAt", "IsDeleted", "OrganizationId", "ProjectId", "EnvironmentId", "Name", "Kind", "Username", "KeySecretName", "PublicKey", "DeployPath", "KeepReleases", "Settings", "AllowedImages", "Version", "CreatedByUserId"
`

